def _build_path(namespace: str) -> ParameterPath | None:
    """Turn a go-validator `namespace` into a parameter path, or `None` if it does not resolve.

    Strips the leading `Body` struct segment, converts standalone `[N]` segments to
    integer indices, and lower-cases the first letter of each named segment.
    """
    if not namespace:
        return None
    segments = namespace.split(".")
    if segments and segments[0] == "Body":
        segments = segments[1:]
    path: list[str | int] = []
    for segment in segments:
        match = _ARRAY_INDEX.fullmatch(segment)
        if match is not None:
            path.append(int(match.group(1)))
            continue
